const backendConnectionLabel=item=>!item.chargerConnected?'Proxy → backoffice niet meetbaar':!item.backendConnected?'Proxy → backoffice verbroken':commandDegraded(item)?'Proxy → backoffice open · lader antwoordt niet':ocppOnline(item)?'Proxy → backoffice verbonden · OCPP actief':item.connectionDiagnostics?.backendTrafficSeen?'Proxy → backoffice verbonden · laatste bericht '+age(directionalTime(item,'backend')):'Proxy → backoffice open · wacht op OCPP';
