function draw(history){const svg=$('chart'),ns='http://www.w3.org/2000/svg';svg.replaceChildren();if(!history.length)return;const end=history.at(-1).time,start=end-120000,top=Math.max(6000,...history.map(p=>Math.max(p.pvW,p.chargeW)))*1.1,add=(tag,a,t)=>{const n=document.createElementNS(ns,tag);Object.entries(a).forEach(([k,v])=>n.setAttribute(k,v));if(t)n.textContent=t;svg.append(n);};for(let i=0;i<4;i++){const y=15+i*48;add('line',{x1:48,x2:625,y1:y,y2:y,stroke:'#e3e9ef'});add('text',{x:0,y:y+4},(top*(1-i/3)/1000).toFixed(1)+' kW');}for(const[key,color]of[['pvW','#d3912d'],['chargeW','#2684c7']])add('polyline',{points:history.map(p=>(48+Math.max(0,(p.time-start)/120000)*577).toFixed(1)+','+(159-p[key]/top*144).toFixed(1)).join(' '),fill:'none',stroke:color,'stroke-width':3});}

